insert into public.embed_domains (domain, note) values
  ('lichess.org', 'Widget officiel « Embed the daily puzzle » (lichess.org/developers)')
insert into public.games (id, slug, title, tagline, description, instructions, genre, cover_url, banner_url, launch_mode, launch_url, source_url, developer, license_status, license_notes, compatibility, controls, orientation, featured, featured_rank, supports_scores, status, published_at, created_at) values
  ('6f1c2a10-0000-4000-8000-000000000001', 'system-breach', 'System Breach', 'Infiltre le réseau, abats trois boss, deviens SYSTEM ARCHITECT.', 'Plateformer d''action cyberpunk en trois secteurs. Saute de plateforme en plateforme, esquive les grilles laser, détruis les drones de sécurité au blaster ou en leur sautant dessus, enchaîne les combos et affronte trois boss multi-phases jusqu''au cœur du mainframe CORE-OMEGA. Mode contre-la-montre et rang final S/A/B/C inclus.', 'Traverse chaque secteur jusqu''au portail de sortie. Le portail ne s''ouvre qu''après avoir vaincu le boss du secteur. Les boss deviennent VULNÉRABLES par intermittence : c''est le moment de frapper, les dégâts sont multipliés par 2,5. Active les balises de checkpoint pour réapparaître plus loin et récupérer de l''intégrité. Ramasse tous les fragments d''un secteur pour le bonus FULL DECRYPT.', array['action', 'platformer', 'arcade']::text[], '/covers/system-breach.jpg', '/covers/system-breach-banner.jpg', 'hosted'::public.launch_mode, '/games/system-breach/index.html', null, 'Euloge', 'owned'::public.license_status, 'Jeu original du propriétaire de la plateforme. Bibliothèques tierces : voir games/system-breach/THIRD_PARTY_NOTICES.md.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":true,"verified":true}'::jsonb, '[{"device":"keyboard","input":"A / D ou ← / →","action":"Se déplacer"},{"device":"keyboard","input":"W / ↑ / Espace","action":"Sauter / double saut"},{"device":"keyboard","input":"J / X / F","action":"Tirer au Cyber Blaster"},{"device":"keyboard","input":"Shift / L / C","action":"Dash (invulnérable un court instant)"},{"device":"keyboard","input":"S / ↓","action":"Descendre d''une plateforme"},{"device":"keyboard","input":"Échap / P","action":"Pause"},{"device":"mouse","input":"Clic sur le jeu","action":"Tirer"},{"device":"touch","input":"Boutons à l''écran","action":"Déplacement, saut, tir, dash"}]'::jsonb, 'landscape', true, 1, true, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000002', 'lichess-daily-puzzle', 'Puzzle d''échecs du jour', 'Un nouveau problème d''échecs chaque jour, proposé par Lichess.', 'Le puzzle quotidien de Lichess, l''une des plus grandes plateformes d''échecs libres et gratuites. Trouve la meilleure suite de coups directement depuis Euloge Arcade grâce au widget d''intégration officiel de Lichess.', 'Joue les coups en faisant glisser les pièces. Trouve la combinaison gagnante. Un nouveau puzzle est publié chaque jour ; pour en résoudre d''autres, ouvre Lichess sur son site officiel.', array['puzzle', 'strategy', 'board']::text[], '/covers/lichess-daily-puzzle.jpg', '/covers/lichess-daily-puzzle-banner.jpg', 'embed'::public.launch_mode, 'https://lichess.org/training/frame?theme=brown&bg=dark', 'https://lichess.org/training', 'Lichess (lichess.org)', 'embed_permitted'::public.license_status, 'Widget « Embed the daily puzzle » mis à disposition par Lichess pour l''intégration sur des sites tiers (lichess.org/developers). Lichess est un logiciel libre (AGPL-3.0). Euloge Arcade n''est pas affilié à Lichess.', '{"keyboard":false,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[{"device":"mouse","input":"Glisser-déposer","action":"Déplacer une pièce"},{"device":"touch","input":"Toucher la pièce puis la case","action":"Déplacer une pièce"}]'::jsonb, 'portrait', true, 2, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000003', 'krunker', 'Krunker.io', 'FPS multijoueur nerveux, jouable dans le navigateur.', 'Krunker.io est un jeu de tir à la première personne multijoueur en voxels, rapide et compétitif, qui se joue directement dans le navigateur. Son site n''autorise pas l''intégration : il s''ouvre sur sa page officielle.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel. Les commandes et les modes de jeu sont présentés directement dans Krunker.', array['fps', 'action']::text[], '/covers/krunker.jpg', '/covers/krunker-banner.jpg', 'external'::public.launch_mode, 'https://krunker.io/', 'https://krunker.io/', null, 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Le site refuse l''intégration (X-Frame-Options: SAMEORIGIN, vérifié le 2026-10-10). Marque et contenus appartenant à leurs détenteurs respectifs.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', true, 3, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000004', '2048', '2048', 'Fusionne les tuiles jusqu''à atteindre 2048.', 'Le célèbre puzzle de Gabriele Cirulli : fais glisser les tuiles, fusionne les nombres identiques et vise la tuile 2048. Le jeu s''ouvre sur son site officiel, qui n''autorise pas l''intégration.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel. Utilise les flèches du clavier ou glisse ton doigt pour déplacer toutes les tuiles.', array['puzzle', 'arcade']::text[], '/covers/2048.jpg', '/covers/2048-banner.jpg', 'external'::public.launch_mode, 'https://play2048.co/', 'https://play2048.co/', 'Gabriele Cirulli', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Le site limite l''intégration à ses propres domaines (CSP frame-ancestors, vérifié le 2026-10-10).', '{"keyboard":true,"mouse":false,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000005', 'lichess', 'Lichess — Échecs en ligne', 'Des parties d''échecs gratuites, sans publicité, contre le monde entier.', 'Lichess est un serveur d''échecs libre, gratuit et sans publicité : parties rapides, tournois, analyse et entraînement. Le site complet n''autorise pas l''intégration et s''ouvre sur sa page officielle. Pour jouer sans quitter Euloge Arcade, essaie le puzzle du jour.', 'Le jeu s''ouvre dans un nouvel onglet, sur lichess.org. Crée une partie rapide ou joue contre l''ordinateur ; aucun compte n''est obligatoire.', array['strategy', 'board']::text[], '/covers/lichess.jpg', '/covers/lichess-banner.jpg', 'external'::public.launch_mode, 'https://lichess.org/', 'https://lichess.org/', 'Lichess (lichess.org)', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement (X-Frame-Options: DENY, vérifié le 2026-10-10). Euloge Arcade n''est pas affilié à Lichess.', '{"keyboard":false,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-09T00:00:00Z', '2026-10-09T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000006', 'quakeworld', 'QuakeWorld', 'Le multijoueur Quake original, directement dans le navigateur.', 'Un projet non commercial de préservation permet de jouer à QuakeWorld en multijoueur dans le navigateur, jusqu''à huit joueurs. Cette version non officielle est propulsée par le moteur FTE QuakeWorld et s''ouvre sur le site du projet.', 'Le jeu s''ouvre dans un nouvel onglet. Saisis un nom de joueur, lance la partie puis rejoins une arène multijoueur. Un clavier et une souris sont recommandés.', array['fps', 'action', 'retro']::text[], '/covers/quakeworld.jpg', '/covers/quakeworld-banner.jpg', 'external'::public.launch_mode, 'https://q1.pieter.com/', 'https://q1.pieter.com/', 'pieter.com / FTE QuakeWorld', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet non commercial et non officiel partagé par @RadiantOpti. Aucun fichier de jeu n''est hébergé par Euloge Arcade. Page du projet accessible et attribution affichée, vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000007', 'surfd', 'Surfd', 'Prends de la vitesse sur des rampes inspirées du surf Source.', 'Surfd est un jeu de surf gratuit conçu pour le navigateur : glisse le long des rampes, maîtrise les transferts et améliore ton chrono sur des parcours classiques. Il propose des parties solo et des serveurs communautaires.', 'Le jeu s''ouvre dans un nouvel onglet. Utilise W, A, S et D pour te déplacer, la souris pour orienter ta trajectoire, Espace ou la molette pour sauter et Échap pour ouvrir le menu.', array['action', 'sports', 'racing']::text[], '/covers/surfd.jpg', '/covers/surfd-banner.jpg', 'external'::public.launch_mode, 'https://surfd.net/', 'https://surfd.net/', '@0yield', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet original partagé par @RadiantOpti. Aucun contenu du jeu n''est hébergé par Euloge Arcade. Page de jeu, crédits et commandes accessibles, vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000008', 'quake-2', 'Quake II', 'Des arènes multijoueur rétro, sans installation.', 'Ce projet non commercial de préservation fait fonctionner Quake II en multijoueur dans le navigateur, jusqu''à huit joueurs. Il s''agit d''une adaptation non officielle propulsée par FTE QuakeWorld.', 'Le jeu s''ouvre dans un nouvel onglet. Saisis un nom de joueur puis lance une partie multijoueur. Un clavier et une souris sont recommandés.', array['fps', 'action', 'retro']::text[], '/covers/quake-2.jpg', '/covers/quake-2-banner.jpg', 'external'::public.launch_mode, 'https://q2.pieter.com/', 'https://q2.pieter.com/', 'pieter.com / FTE QuakeWorld', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet non commercial et non officiel partagé par @RadiantOpti. Aucun fichier de jeu n''est hébergé par Euloge Arcade. Page du projet accessible et attribution affichée, vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000009', 'urban-terror', 'Urban Terror', 'Un FPS tactique multijoueur préservé en WebAssembly.', 'Cette adaptation web non commerciale compile le moteur ioUrbanTerror en WebAssembly pour proposer des parties multijoueur dans le navigateur. Le premier lancement télécharge les données du jeu, ensuite conservées dans le cache du navigateur.', 'Le jeu s''ouvre dans un nouvel onglet. Prévois un premier chargement plus long, puis saisis un nom de joueur et rejoins une partie. Le projet recommande Chrome sur ordinateur.', array['fps', 'action']::text[], '/covers/urban-terror.jpg', '/covers/urban-terror-banner.jpg', 'external'::public.launch_mode, 'https://ut.pieter.com/', 'https://www.urbanterror.info/', 'FrozenSand / pieter.com', 'link_only'::public.license_status, 'Lien externe uniquement vers une préservation web non officielle et non commerciale partagée par @RadiantOpti. Urban Terror appartient à FrozenSand. Aucun fichier de jeu n''est hébergé par Euloge Arcade. Page accessible et attribution affichée, vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000010', 'black-ops-zombies-browser', 'Black Ops Zombies (navigateur)', 'Un projet communautaire de survie contre les zombies.', 'Le lien partagé par @RadiantOpti ouvre une sélection de cartes Zombies dans le navigateur. Ce projet tiers non officiel n''est pas affilié à Activision.', 'Le jeu s''ouvre dans un nouvel onglet. Consulte les indications du site tiers avant de lancer une carte.', array['fps', 'action']::text[], '/covers/black-ops-zombies-browser.jpg', '/covers/black-ops-zombies-browser-banner.jpg', 'external'::public.launch_mode, 'https://vel.gg/bo1z', 'https://vel.gg/bo1z', null, 'link_only'::public.license_status, 'Lien externe uniquement vers le projet tiers partagé par @RadiantOpti. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10 ; fonctionnement complet non validé.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000011', 'halo-ce-browser', 'Halo: Combat Evolved (navigateur)', 'Une adaptation communautaire de Halo CE dans le navigateur.', 'Le lien partagé par @RadiantOpti ouvre un projet communautaire permettant de lancer Halo: Combat Evolved dans le navigateur. Des fichiers provenant de ta propre copie peuvent être nécessaires.', 'Le jeu s''ouvre dans un nouvel onglet. Suis les instructions du projet et utilise uniquement les fichiers d''une copie que tu possèdes.', array['fps', 'action', 'retro']::text[], '/covers/halo-ce-browser.jpg', '/covers/halo-ce-browser-banner.jpg', 'external'::public.launch_mode, 'https://mitchellhynes.com/halo/', 'https://mitchellhynes.com/halo/', 'Projet communautaire', 'link_only'::public.license_status, 'Lien externe uniquement. Projet non officiel partagé par @RadiantOpti ; aucun fichier Halo n''est fourni par Euloge Arcade. Destination accessible le 2026-10-10 ; exigences exactes non validées.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000012', 'skate-3-browser', 'Skate 3 — Fan Game', 'Un projet de skate utilisant les données de ta propre copie.', 'Ce fan game diffusé par @RadiantOpti charge les données converties d''une copie de Skate 3 appartenant au joueur. Le premier chargement peut être long.', 'Le jeu s''ouvre dans un nouvel onglet. Prépare les données de ta propre copie en suivant exclusivement les instructions du projet.', array['sports', 'action']::text[], '/covers/skate-3-browser.jpg', '/covers/skate-3-browser-banner.jpg', 'external'::public.launch_mode, 'https://skate.aaddpp.lol/', 'https://skate.aaddpp.lol/', 'Projet communautaire', 'link_only'::public.license_status, 'Lien externe uniquement vers un fan game non officiel. Le site indique que les données doivent venir de la propre copie du joueur. Aucun fichier Skate 3 n''est fourni par Euloge Arcade. Vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":true,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000013', 'diablo-web', 'Diablo Web', 'Le moteur de Diablo dans le navigateur, avec tes propres données.', 'Diablo Web est un projet navigateur basé sur le jeu classique. Selon la version utilisée, les données d''une copie personnelle de Diablo peuvent être nécessaires.', 'Le jeu s''ouvre dans un nouvel onglet. Suis les instructions du projet et fournis uniquement les données d''un jeu que tu possèdes.', array['action', 'retro']::text[], '/covers/diablo-web.jpg', '/covers/diablo-web-banner.jpg', 'external'::public.launch_mode, 'https://johnimril.github.io/diablo_web/', 'https://johnimril.github.io/diablo_web/', 'johnimril', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet partagé par @RadiantOpti. Aucun fichier Diablo n''est distribué par Euloge Arcade. Destination accessible le 2026-10-10 ; chargement complet non validé.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000014', 'moon-zombies', 'Moon Zombies', 'Une carte Zombies communautaire sur la Lune.', 'Cette entrée conserve le lien Moon Zombies partagé dans la collection. Lors de la vérification, le domaine a redirigé vers une destination différente non validée.', 'Lien conservé à titre de référence. Il est désactivé dans le catalogue tant que sa destination n''est pas de nouveau fiable.', array['fps', 'action']::text[], '/covers/moon-zombies.jpg', '/covers/moon-zombies-banner.jpg', 'external'::public.launch_mode, 'https://moon-zombies.pages.dev/', 'https://moon-zombies.pages.dev/', null, 'link_only'::public.license_status, 'Lien externe historique partagé par @RadiantOpti. Le 2026-10-10, il redirigeait vers un raccourcisseur tiers (lkgp.pro) non validé ; aucun lancement n''est proposé tant que le lien reste signalé indisponible. Aucun autre site légitime hébergeant cette carte n''a été trouvé. Alternative libre et jouable : Nazi Zombies: Portable (nzp.gay), présente dans le catalogue.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000015', 'kino-der-toten-browser', 'Kino der Toten', 'Une adaptation communautaire de la carte Zombies du théâtre.', 'Cette entrée conserve le lien Kino der Toten partagé dans la collection. Lors de la vérification, le domaine a redirigé vers une destination différente non validée.', 'Lien conservé à titre de référence. Il est désactivé dans le catalogue tant que sa destination n''est pas de nouveau fiable.', array['fps', 'action']::text[], '/covers/kino-der-toten-browser.jpg', '/covers/kino-der-toten-browser-banner.jpg', 'external'::public.launch_mode, 'https://kino-der-toten.pages.dev/', 'https://kino-der-toten.pages.dev/', null, 'link_only'::public.license_status, 'Lien externe historique partagé par @RadiantOpti. Le 2026-10-10, il redirigeait vers un raccourcisseur tiers (lkgp.pro) non validé ; aucun lancement n''est proposé tant que le lien reste signalé indisponible. Aucun autre site légitime hébergeant cette carte n''a été trouvé. Alternative libre et jouable : Nazi Zombies: Portable (nzp.gay), présente dans le catalogue.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000016', 'cheese-cube-browser', 'Cheese Cube Zombies', 'Un défi Zombies communautaire inspiré de Cheese Cube.', 'Cette entrée conserve le lien Cheese Cube partagé dans la collection. Lors de la vérification, le domaine a redirigé vers une destination différente non validée.', 'Lien conservé à titre de référence. Il est désactivé dans le catalogue tant que sa destination n''est pas de nouveau fiable.', array['fps', 'action']::text[], '/covers/cheese-cube-browser.jpg', '/covers/cheese-cube-browser-banner.jpg', 'external'::public.launch_mode, 'https://cheese-cube.pages.dev/', 'https://cheese-cube.pages.dev/', null, 'link_only'::public.license_status, 'Lien externe historique partagé par @RadiantOpti. Le 2026-10-10, il redirigeait vers un raccourcisseur tiers (lkgp.pro) non validé ; aucun lancement n''est proposé tant que le lien reste signalé indisponible. Aucun autre site légitime hébergeant cette carte n''a été trouvé. Alternative libre et jouable : Nazi Zombies: Portable (nzp.gay), présente dans le catalogue.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000017', 'vibe-slops-2', 'Claude of Duty: Vibe Slops II', 'Le projet communautaire associé à l''entrée Black Ops 2.', 'La publication présentait cette destination comme Black Ops 2, mais le projet lié portait le nom Claude of Duty: Vibe Slops II. Le domaine renvoie actuellement une erreur 404.', 'Lien conservé à titre de référence. Il est désactivé dans le catalogue tant qu''une version fonctionnelle n''est pas retrouvée.', array['fps', 'action']::text[], '/covers/vibe-slops-2.jpg', '/covers/vibe-slops-2-banner.jpg', 'external'::public.launch_mode, 'https://vibeslops.luckeysystems.com/', 'https://vibeslops.luckeysystems.com/', 'Luckey Systems', 'link_only'::public.license_status, 'Lien externe historique partagé par @RadiantOpti. Le domaine ne répondait plus le 2026-10-10 et aucune adresse de remplacement n''a été trouvée ; aucun lancement n''est proposé tant que le lien reste signalé indisponible.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000018', 'skate-rust', 'Skate × Rust', 'Skate, exploration et action dans une expérience communautaire.', 'Ce projet communautaire mélange déplacement en skateboard, exploration et mécaniques de tir dans une expérience jouable depuis le navigateur.', 'Le jeu s''ouvre dans un nouvel onglet. Le site documente les commandes clavier, souris et les fonctions de skateboard.', array['sports', 'action']::text[], '/covers/skate-rust.jpg', '/covers/skate-rust-banner.jpg', 'external'::public.launch_mode, 'https://global-terror-skate-rust.fvc3less.workers.dev/full.html', 'https://global-terror-skate-rust.fvc3less.workers.dev/full.html', 'Projet communautaire', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet partagé par @RadiantOpti. Aucun contenu n''est hébergé par Euloge Arcade. Page et commandes accessibles le 2026-10-10 ; fonctionnement complet non validé.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000019', 'halo-ce-mobile', 'Halo CE Mobile', 'Halo CE dans le navigateur avec les données de ta propre copie.', 'Halo CE Mobile reconstruit Halo: Combat Evolved pour le navigateur et les appareils mobiles. Le projet exige une image disque Xbox appartenant au joueur et ne fournit aucune donnée du jeu.', 'Le jeu s''ouvre dans un nouvel onglet. Ajoute l''image disque de ta propre copie, puis suis l''assistant du projet. Jusqu''à 1,8 Go peuvent être stockés localement.', array['fps', 'action', 'retro']::text[], '/covers/halo-ce-mobile.jpg', '/covers/halo-ce-mobile-banner.jpg', 'external'::public.launch_mode, 'https://hcemobile.com/', 'https://hcemobile.com/', 'HCEMobile', 'link_only'::public.license_status, 'Lien externe uniquement vers un projet non officiel déclarant suivre les règles d''utilisation du contenu Microsoft. Le site exige les données de la propre copie du joueur. Aucun fichier Halo n''est fourni par Euloge Arcade. Vérifié le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":true,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000020', 'pes-6-web', 'PES 6 Web Online', 'Le football PSP recompilé pour WebAssembly.', 'PES 6 Web Online exécute une version PSP de Pro Evolution Soccer 6 dans le navigateur avec clavier, manette, commandes tactiles, sauvegardes et matchs en ligne.', 'Le jeu s''ouvre dans un nouvel onglet. Choisis une version audio ou la version légère, puis configure les commandes depuis le menu du site.', array['sports', 'retro']::text[], '/covers/pes-6-web.jpg', '/covers/pes-6-web-banner.jpg', 'external'::public.launch_mode, 'https://pes6.optijuegos.net/', 'https://pes6.optijuegos.net/', 'OptiJuegos', 'link_only'::public.license_status, 'Lien externe uniquement vers un projet tiers déclarant ne pas être affilié à Konami. Euloge Arcade n''héberge ni le jeu ni ses fichiers. Page et avertissement d''affiliation accessibles le 2026-10-10.', '{"keyboard":true,"mouse":false,"gamepad":true,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000021', 'gta-vice-city-wasm', 'GTA: Vice City — WASM', 'Un port WebAssembly utilisant les fichiers de ta propre copie.', 'Ce projet WebAssembly charge localement une archive game.tar.gz créée à partir d''une copie personnelle de GTA: Vice City. Les fichiers restent dans le stockage privé du navigateur.', 'Le jeu s''ouvre dans un nouvel onglet. Prépare l''archive à partir de ta propre copie en suivant la procédure du projet, puis importe-la une seule fois.', array['action', 'retro']::text[], '/covers/gta-vice-city-wasm.jpg', '/covers/gta-vice-city-wasm-banner.jpg', 'external'::public.launch_mode, 'https://joncodeofficial.github.io/gta-vice-city-wasm/', 'https://joncodeofficial.github.io/gta-vice-city-wasm/', 'joncodeofficial', 'link_only'::public.license_status, 'Lien externe uniquement. Le projet demande une archive créée depuis la propre copie du joueur ; aucun fichier GTA n''est fourni ou hébergé par Euloge Arcade. Instructions accessibles le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000022', 'simpsons-hit-and-run-wasm', 'The Simpsons: Hit & Run — WASM', 'Un port communautaire de Springfield dans le navigateur.', 'Le lien partagé par @RadiantOpti ouvre un port WebAssembly communautaire de The Simpsons: Hit & Run. Sa provenance et ses conditions de redistribution restent à vérifier auprès du projet.', 'Le jeu s''ouvre dans un nouvel onglet. Le chargement peut être long et le fonctionnement dépend du navigateur.', array['action', 'racing', 'retro']::text[], '/covers/simpsons-hit-and-run-wasm.jpg', '/covers/simpsons-hit-and-run-wasm-banner.jpg', 'external'::public.launch_mode, 'https://shar-wasm.cjoseph.workers.dev/?skipmovie=', 'https://shar-wasm.cjoseph.workers.dev/?skipmovie=', 'Projet communautaire', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet tiers partagé par @RadiantOpti. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. La page répondait le 2026-10-10 ; fonctionnement et droits du projet non validés.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000023', 'quake-3-browser', 'Quake III Arena', 'Des arènes Quake III multijoueur dans le navigateur.', 'Cette entrée correspond au projet Quake III partagé par @RadiantOpti. La vérification automatisée de la destination a expiré avant de confirmer le chargement du jeu.', 'Le jeu s''ouvre dans un nouvel onglet. Un navigateur de bureau, un clavier et une souris sont recommandés.', array['fps', 'action', 'retro']::text[], '/covers/quake-3-browser.jpg', '/covers/quake-3-browser-banner.jpg', 'external'::public.launch_mode, 'https://q3.pieter.com/', 'https://q3.pieter.com/', 'pieter.com', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet non officiel partagé par @RadiantOpti. Aucun fichier Quake III n''est hébergé par Euloge Arcade. La vérification du 2026-10-10 a expiré ; disponibilité laissée non contrôlée.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000024', 'return-to-castle-wolfenstein-browser', 'Return to Castle Wolfenstein', 'Le multijoueur Wolfenstein préservé dans le navigateur.', 'Ce projet non commercial propose une préservation web multijoueur de Return to Castle Wolfenstein, compilée pour fonctionner dans un navigateur moderne.', 'Le jeu s''ouvre dans un nouvel onglet. Saisis un nom de joueur puis rejoins une partie multijoueur.', array['fps', 'action', 'retro']::text[], '/covers/return-to-castle-wolfenstein-browser.jpg', '/covers/return-to-castle-wolfenstein-browser-banner.jpg', 'external'::public.launch_mode, 'https://rtcw.pieter.com/', 'https://rtcw.pieter.com/', 'pieter.com', 'link_only'::public.license_status, 'Lien externe uniquement vers un projet de préservation non officiel et non commercial. Aucun fichier du jeu n''est hébergé par Euloge Arcade. Page et attribution accessibles le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000025', 'half-life-web', 'Half-Life Web', 'Une adaptation web communautaire du classique de Valve.', 'Half-Life Web est un projet communautaire permettant de lancer un moteur compatible Half-Life dans le navigateur. Des données provenant d''une copie personnelle peuvent être nécessaires.', 'Le jeu s''ouvre dans un nouvel onglet. Consulte les instructions du projet et utilise uniquement les fichiers d''une copie que tu possèdes.', array['fps', 'action', 'retro']::text[], '/covers/half-life-web.jpg', '/covers/half-life-web-banner.jpg', 'external'::public.launch_mode, 'https://pixelsuft.github.io/hl/', 'https://pixelsuft.github.io/hl/', 'Pixelsuft', 'link_only'::public.license_status, 'Lien externe uniquement vers le projet tiers partagé par @RadiantOpti. Aucun fichier Half-Life n''est fourni par Euloge Arcade. Page accessible le 2026-10-10 ; fonctionnement complet non validé.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000026', 'webxash-half-life-cs16', 'WebXash — Half-Life / CS 1.6', 'Un moteur web compatible avec les données Half-Life et Counter-Strike.', 'WebXash adapte le moteur Xash3D au navigateur pour charger des données compatibles Half-Life ou Counter-Strike 1.6 provenant d''une copie personnelle.', 'Le jeu s''ouvre dans un nouvel onglet. Charge uniquement les fichiers d''un jeu que tu possèdes en suivant la documentation du projet.', array['fps', 'action', 'retro']::text[], '/covers/webxash-half-life-cs16.jpg', '/covers/webxash-half-life-cs16-banner.jpg', 'external'::public.launch_mode, 'https://x8bitrain.github.io/webXash/', 'https://x8bitrain.github.io/webXash/', 'x8bitrain / Xash3D', 'link_only'::public.license_status, 'Lien externe uniquement vers le moteur web partagé par @RadiantOpti. Aucun fichier Half-Life ou Counter-Strike n''est fourni par Euloge Arcade. Destination accessible le 2026-10-10 ; chargement complet non validé.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000027', 'nazi-zombies-portable', 'Nazi Zombies: Portable', 'Le mode Zombies revisité, libre et open source, jouable en WebGL.', 'Nazi Zombies: Portable (NZ:P) est un « demake » libre du mode Zombies de Call of Duty, développé par la NZ:P Team. Le code est sous licence GPLv2 et les ressources sous CC-BY-SA 4.0. La version WebGL officielle se lance directement dans le navigateur. Projet non affilié à Activision ni à Treyarch.', 'Le jeu s''ouvre dans un nouvel onglet. Clique sur « Click To Begin! » puis attends le chargement. Clavier et souris recommandés.', array['fps', 'action', 'retro']::text[], '/covers/nazi-zombies-portable.jpg', '/covers/nazi-zombies-portable-banner.jpg', 'external'::public.launch_mode, 'https://nzp.gay/', 'https://nzp.gay/', 'NZ:P Team', 'link_only'::public.license_status, 'Lien vers la version WebGL officielle de la NZ:P Team (référencée sur nzp-team.itch.io). Projet open source : code GPLv2, ressources CC-BY-SA 4.0 (github.com/nzp-team/nzportable). Aucun fichier n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000028', 'celeste-classic', 'Celeste Classic', 'Le prototype PICO-8 de Celeste, en 30 niveaux.', 'La version originale de Celeste, créée en quatre jours pour PICO-8 par Maddy Thorson et Noel Berry. Grimpe la montagne en sautant, en t''agrippant aux murs et en utilisant ton dash aérien.', 'Le jeu s''ouvre sur la page Lexaloffle : clique sur le lecteur. Flèches pour bouger, C pour sauter, X pour le dash.', array['platformer', 'retro']::text[], '/covers/celeste-classic.jpg', '/covers/celeste-classic-banner.jpg', 'external'::public.launch_mode, 'https://www.lexaloffle.com/bbs/?tid=2145', 'https://www.lexaloffle.com/bbs/?tid=2145', 'Maddy Thorson & Noel Berry', 'link_only'::public.license_status, 'Lien vers la page officielle du jeu sur Lexaloffle (éditeur de PICO-8). Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":false,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000029', 'tetris', 'Tetris', 'Le Tetris officiel, gratuit dans le navigateur.', 'La version web officielle de Tetris proposée par The Tetris Company. Empile les tétriminos, complète des lignes et tiens le plus longtemps possible.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['puzzle', 'arcade', 'retro']::text[], '/covers/tetris.jpg', '/covers/tetris-banner.jpg', 'external'::public.launch_mode, 'https://play.tetris.com/', 'https://play.tetris.com/', 'The Tetris Company', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000030', 'a-dark-room', 'A Dark Room', 'Un jeu d''aventure textuel minimaliste.', 'Tout commence dans une pièce sombre, avec un feu à allumer. Ce jeu narratif incrémental de Doublespeak Games se dévoile peu à peu en village, en exploration et en mystère. Son code est publié en open source (MPL 2.0).', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['strategy', 'retro']::text[], '/covers/a-dark-room.jpg', '/covers/a-dark-room-banner.jpg', 'external'::public.launch_mode, 'https://adarkroom.doublespeakgames.com/', 'https://adarkroom.doublespeakgames.com/', 'Doublespeak Games', 'link_only'::public.license_status, 'Lien vers le site officiel du jeu (code source MPL 2.0 sur github.com/doublespeakgames/adarkroom). Aucun fichier n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":false,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000031', 'little-alchemy-2', 'Little Alchemy 2', 'Combine les éléments et découvre plus de 700 créations.', 'Pars de l''air, de l''eau, de la terre et du feu, puis combine-les pour créer la vie, des inventions et des mythes. Un puzzle de découverte de Recloak.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['puzzle']::text[], '/covers/little-alchemy-2.jpg', '/covers/little-alchemy-2-banner.jpg', 'external'::public.launch_mode, 'https://littlealchemy2.com/', 'https://littlealchemy2.com/', 'Recloak', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":false,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000032', 'slither-io', 'slither.io', 'Grandis ton serpent face aux autres joueurs.', 'Le célèbre jeu multijoueur en ligne : mange les orbes lumineux pour grandir et fais foncer les autres serpents dans ton corps.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['arcade', 'action']::text[], '/covers/slither-io.jpg', '/covers/slither-io-banner.jpg', 'external'::public.launch_mode, 'https://slither.io/', 'https://slither.io/', 'Steve Howse (Lowtech Studios)', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":false,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000033', 'diep-io', 'diep.io', 'Améliore ton tank et domine l''arène.', 'Jeu multijoueur de tanks vu de dessus : détruis des formes et des adversaires pour gagner de l''expérience, puis fais évoluer ton tank en dizaines de classes.', 'Le jeu s''ouvre dans un nouvel onglet. WASD pour bouger, la souris pour viser et tirer.', array['action', 'arcade']::text[], '/covers/diep-io.jpg', '/covers/diep-io-banner.jpg', 'external'::public.launch_mode, 'https://diep.io/', 'https://diep.io/', 'Zeach (Addicting Games)', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000034', 'skribbl-io', 'skribbl.io', 'Dessine et fais deviner, entre amis ou en public.', 'Le jeu de dessin multijoueur : un joueur dessine un mot, les autres devinent le plus vite possible. Crée une salle privée pour jouer entre amis.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['arcade']::text[], '/covers/skribbl-io.jpg', '/covers/skribbl-io-banner.jpg', 'external'::public.launch_mode, 'https://skribbl.io/', 'https://skribbl.io/', 'skribbl.io', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000035', 'line-rider', 'Line Rider', 'Trace des pistes, regarde ton luge-man les dévaler.', 'Le classique jeu bac à sable : dessine des lignes et regarde la physique emporter le pilote sur ta création. Version web officielle.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['sports', 'puzzle']::text[], '/covers/line-rider.jpg', '/covers/line-rider-banner.jpg', 'external'::public.launch_mode, 'https://www.linerider.com/', 'https://www.linerider.com/', 'Line Rider', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000036', 'wordle', 'Wordle', 'Un mot de cinq lettres à trouver en six essais.', 'Le jeu de mots quotidien du New York Times : trouve le mot secret (en anglais) grâce aux indices de couleur.', 'Le jeu s''ouvre dans un nouvel onglet, sur son site officiel.', array['puzzle']::text[], '/covers/wordle.jpg', '/covers/wordle-banner.jpg', 'external'::public.launch_mode, 'https://www.nytimes.com/games/wordle/index.html', 'https://www.nytimes.com/games/wordle/index.html', 'The New York Times', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000037', 'shell-shockers', 'Shell Shockers', 'Le FPS multijoueur… avec des œufs armés.', 'FPS multijoueur gratuit de Blue Wizard Digital : choisis ton arme et casse la coquille des autres œufs, en équipe ou en mêlée générale.', 'Le jeu s''ouvre dans un nouvel onglet. WASD pour bouger, la souris pour viser et tirer, Espace pour sauter.', array['fps', 'action']::text[], '/covers/shell-shockers.jpg', '/covers/shell-shockers-banner.jpg', 'external'::public.launch_mode, 'https://shellshock.io/', 'https://shellshock.io/', 'Blue Wizard Digital', 'link_only'::public.license_status, 'Lien vers le site officiel uniquement. Aucun fichier ni visuel du jeu n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":true,"gamepad":false,"touch":false,"verified":false}'::jsonb, '[]'::jsonb, 'landscape', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z'),
  ('6f1c2a10-0000-4000-8000-000000000038', 'hextris', 'Hextris', 'Un puzzle rapide inspiré de Tetris, sur un hexagone.', 'Fais tourner l''hexagone pour regrouper les blocs de même couleur qui tombent avant qu''ils ne débordent. Jeu open source (GPLv3).', 'Le jeu s''ouvre dans un nouvel onglet. Flèches gauche/droite (ou touche des deux côtés de l''écran) pour tourner l''hexagone.', array['puzzle', 'arcade']::text[], '/covers/hextris.jpg', '/covers/hextris-banner.jpg', 'external'::public.launch_mode, 'https://hextris.github.io/hextris/', 'https://hextris.github.io/hextris/', 'Hextris', 'link_only'::public.license_status, 'Lien vers la version publiée par le projet sur GitHub Pages (code GPLv3, github.com/Hextris/hextris). Aucun fichier n''est hébergé par Euloge Arcade. Page accessible le 2026-10-10.', '{"keyboard":true,"mouse":false,"gamepad":false,"touch":true,"verified":false}'::jsonb, '[]'::jsonb, 'any', false, null, false, 'published'::public.game_status, '2026-10-10T00:00:00Z', '2026-10-10T00:00:00Z')
